function repetir<T>(valor: T, vezes: number): T[] {
  return Array.from({ length: vezes }, () => valor);
}

// um único candidato, vindo do primeiro argumento
const setes = repetir(7, 3);      // number[]
const olas = repetir("ola", 2);   // string[]

function preencher<T>(itens: T[], omissao: T): T[] {
  return itens.length > 0 ? itens : [omissao];
}

// dois candidatos para o mesmo T, ambos number
const numeros = preencher([1, 2], 0);   // number[]
const textos = preencher(["a"], "");    // string[]

// @ts-expect-error o primeiro argumento já fixou T como number
const misturado = preencher([1, 2], "zero");

console.log(setes, olas, numeros, textos, misturado);

function juntar<T>(a: T, b: T): T[] {
  return [a, b];
}

class Animal {
  constructor(public nome: string) {}
}
class Gato extends Animal {
  ronrona = true;
}

// candidatos diferentes mas compatíveis: fica o supertipo comum
const bichos = juntar(new Gato("kit"), new Animal("rex")); // Animal[]

// @ts-expect-error number e string não têm supertipo comum entre os candidatos
const partido = juntar(1, "um");

// correção 1: escrever o argumento de tipo
const unido = juntar<string | number>(1, "um"); // (string | number)[]

// correção 2: dar um só candidato que já é uma união
function deLista<T>(itens: T[]): T[] {
  return itens;
}
const lista = deLista([1, "um"]); // (string | number)[]

console.log(bichos, partido, unido, lista);

function embrulhar<T>(valor: T): { valor: T } {
  return { valor };
}

const largo = embrulhar("ativo"); // { valor: string }

// 1) as const no argumento
const comAsConst = embrulhar("ativo" as const); // { valor: "ativo" }

// 2) uma constraint que aponte para o primitivo
function embrulharTexto<T extends string>(valor: T): { valor: T } {
  return { valor };
}
const comConstraint = embrulharTexto("ativo"); // { valor: "ativo" }

// 3) parâmetro de tipo const, desde o TypeScript 5.0
function embrulharConst<const T>(valor: T): { valor: T } {
  return { valor };
}
const comConstParam = embrulharConst("ativo"); // { valor: "ativo" }

console.log(largo, comAsConst, comConstraint, comConstParam);

function definir<T>(config: T): T {
  return config;
}
function definirConst<const T>(config: T): T {
  return config;
}

const solto = definir({ modo: "escuro", tamanhos: [10, 20] });
// { modo: string; tamanhos: number[] }

const fixo = definirConst({ modo: "escuro", tamanhos: [10, 20] });
// { readonly modo: "escuro"; readonly tamanhos: readonly [10, 20] }

// @ts-expect-error o const tornou as propriedades só de leitura
fixo.modo = "claro";

console.log(solto, fixo);

function mapear<T, U>(itens: T[], fn: (item: T) => U): U[] {
  return itens.map(fn);
}

// T é fixado por [1, 2, 3]; só depois o callback é tipado e U sai do return
const formatados = mapear([1, 2, 3], (n) => n.toFixed(2)); // string[]

// sem nenhuma fonte para T, o parâmetro do callback fica unknown
function aplicar<T>(fn: (item: T) => void): void {
  console.log(fn);
}
aplicar((item) => {
  // @ts-expect-error item é unknown: nada no sítio da chamada diz o que é T
  console.log(item.length);
});

console.log(formatados);

function encadear<T, U, V>(valor: T, f: (t: T) => U, g: (u: U) => V): V {
  return g(f(valor));
}
const bom = encadear(3, (n) => n.toFixed(2), (s) => s.length); // number

function encadearTrocado<T, U, V>(g: (u: U) => V, f: (t: T) => U, valor: T): V {
  return g(f(valor));
}
// @ts-expect-error s fica unknown: g é tipado antes de U ter sido descoberto
const mau = encadearTrocado((s) => s.length, (n) => n.toFixed(2), 3);

console.log(bom, mau);

interface Resposta<T> {
  dados: { itens: T[]; total: number };
}

function primeiroItem<T>(resposta: Resposta<T>): T {
  return resposta.dados.itens[0];
}

const item = primeiroItem({
  dados: { itens: [{ id: 1, nome: "ana" }], total: 1 },
}); // { id: number; nome: string }

function extrairValor<T>(caixa: { valor: T }): T {
  return caixa.valor;
}
const numero = extrairValor({ valor: 42 });            // number
const literal = extrairValor({ valor: "ok" as const }); // "ok"

console.log(item.nome, numero, literal);

