function primeiroOuOmissao<T>(itens: T[], omissao: T): T {
  return itens.length > 0 ? itens[0] : omissao;
}

const n = primeiroOuOmissao([10, 20], 0);     // number
const s = primeiroOuOmissao(["a"], "vazio");  // string

// @ts-expect-error o primeiro argumento fixa T como number e "zero" não serve como candidato
const errado = primeiroOuOmissao([10, 20], "zero");

// correção: um argumento de tipo explícito que acomode os dois candidatos
const uniao = primeiroOuOmissao<string | number>([10, 20], "zero"); // string | number

console.log(n, s, errado, uniao);

type Guardar = "guardar";

// versão ingénua: o literal alarga-se para string
function criarAcao<T>(tipo: T): { tipo: T } {
  return { tipo };
}
const larga = criarAcao("guardar"); // { tipo: string }
// @ts-expect-error larga.tipo é string, não o literal "guardar"
const falha: Guardar = larga.tipo;

// 1) as const no argumento
const prova1: Guardar = criarAcao("guardar" as const).tipo;

// 2) constraint sobre string
function criarAcaoTexto<T extends string>(tipo: T): { tipo: T } {
  return { tipo };
}
const prova2: Guardar = criarAcaoTexto("guardar").tipo;

// 3) parâmetro de tipo const
function criarAcaoConst<const T>(tipo: T): { tipo: T } {
  return { tipo };
}
const prova3: Guardar = criarAcaoConst("guardar").tipo;

console.log(falha, prova1, prova2, prova3);

function transformarEFiltrar<T, U>(
  itens: T[],
  transformar: (item: T) => U,
  manter: (valor: U) => boolean
): U[] {
  return itens.map(transformar).filter(manter);
}

const precos = transformarEFiltrar([1, 2, 3, 4], (n) => n * 10, (v) => v > 15); // number[]
const iniciais = transformarEFiltrar(["ana", "rui"], (nome) => nome[0], (c) => c !== "r"); // string[]

function trocada<T, U>(
  manter: (valor: U) => boolean,
  transformar: (item: T) => U,
  itens: T[]
): U[] {
  return itens.map(transformar).filter(manter);
}

// @ts-expect-error valor fica unknown: manter é tipado antes de U ter sido descoberto
const partido = trocada((valor) => valor > 15, (n) => n * 10, [1, 2, 3, 4]);

console.log(precos, iniciais, partido);

function acumular<T, A>(itens: T[], inicial: A, passo: (acumulado: A, item: T) => A): A {
  let atual = inicial;
  for (const item of itens) {
    atual = passo(atual, item);
  }
  return atual;
}

// tudo inferido: T = number, A = number
const soma = acumular([1, 2, 3], 0, (total, n) => total + n); // number

// @ts-expect-error A foi inferido como {} a partir do literal e não aceita índice de texto
const mau = acumular(["ana", "ana", "rui"], {}, (conta, nome) => ({ ...conta, [nome]: (conta[nome] ?? 0) + 1 }));

// correção: escrever os argumentos de tipo
const contagens = acumular<string, { [nome: string]: number }>(
  ["ana", "ana", "rui"],
  {},
  (conta, nome) => ({ ...conta, [nome]: (conta[nome] ?? 0) + 1 })
); // { [nome: string]: number }

console.log(soma, mau, contagens);
